// REPORTS v1 (file 12 / Q26, block 19) — the first slice of the reporting
// suite, built ONLY from data the app already captures (no new data entry):
//   · Completed cabs: actual vs standard man-hours, per cab and per product
//     (file 12 suite 2 — "the money report")
//   · Open cabs aging list (suite 1)
//   · Labor hours per employee for the period (suite 3 basics)
//   · Rework count + reasons for the period (suite 5 basics)
//   · CSV export of each table (file 12 universal controls)
// Time basis (C15/Q103): ACTUAL hours = clock coverage on the cab's line
// between start and sign-off — never summed task spans. Times shown in
// Phoenix (Q82). Deeper suites (auto-tune, downtime, forecasting, digests)
// arrive in later blocks; this page is built to grow.
const phxHM = (ts) => ts ? new Date(new Date(ts).getTime() - 7 * 3600000).toISOString().slice(0, 16).replace("T", " ") : "";
const phxDate = (ms) => new Date(ms - 7 * 3600000).toISOString().slice(0, 10);

// Turn the raw clock_event stream (ascending) into closed work intervals:
// a clock_in opens one on its line; the SAME employee's next clock_out of
// any kind closes it. Still-open intervals clip at `now` so live work counts.
// Block 127 (M3, B2): fix-labor hours per order. Pairs each Fix-work clock-in
// (which carries fix_build_id) with the tech's next clock-out and sums the elapsed
// time per build. Non-fix intervals are ignored; a still-open fix counts to now.
// Block 301: hours a BUCKET line (Fix work 15 / Panel prep 19) spent per cab — from punches, never typed.
function bucketHoursByBuild301(evs, lineId) {
  const open = {}, sums = {}, now = Date.now();
  const close = (emp, t) => { const o = open[emp]; if (o) { if (o.line === lineId && o.fix) sums[o.fix] = (sums[o.fix] || 0) + (t - o.start); open[emp] = null; } };
  for (const e of evs) {
    const t = new Date(e.claimed_at).getTime();
    if (e.kind === "clock_in") { close(e.employee_id, t); open[e.employee_id] = { start: t, line: e.line_id, fix: e.fix_build_id }; }
    else close(e.employee_id, t);
  }
  for (const emp in open) { const o = open[emp]; if (o && o.line === lineId && o.fix) sums[o.fix] = (sums[o.fix] || 0) + (now - o.start); }
  const out = {}; for (const k in sums) out[k] = sums[k] / 3600000;
  return out;
}
// Prep hours for a set of cabs: seed by the punches that point at them, then replay those people's days.
async function prepHours301(buildIds) {
  if (!buildIds.length) return {};
  const seed = await db(`clock_event?select=employee_id&voided=is.false&line_id=eq.${PREP_LINE_ID}&fix_build_id=in.(${buildIds.join(",")})&kind=eq.clock_in&limit=2000`);
  if (!seed.length) return {};
  const emps = [...new Set(seed.map((x) => x.employee_id))];
  const evs = await dbAll252(`clock_event?select=employee_id,line_id,kind,fix_build_id,claimed_at&voided=is.false&employee_id=in.(${emps.join(",")})&claimed_at=gte.${new Date(Date.now() - 120 * 86400000).toISOString()}&order=claimed_at.asc,id.asc`);
  return bucketHoursByBuild301(evs, PREP_LINE_ID);
}
const median301 = (xs) => { const a = [...xs].sort((x, y) => x - y); const m = a.length >> 1; return a.length ? (a.length % 2 ? a[m] : Math.round(((a[m - 1] + a[m]) / 2) * 100) / 100) : 0; };
function fixHoursByBuild(evs) {
  const open = {}, sums = {}, now = Date.now();
  const close = (emp, t) => { const o = open[emp]; if (o) { if (o.line === FIX_LINE_ID && o.fix) sums[o.fix] = (sums[o.fix] || 0) + (t - o.start); open[emp] = null; } };
  for (const e of evs) {
    const t = new Date(e.claimed_at).getTime();
    if (e.kind === "clock_in") { close(e.employee_id, t); open[e.employee_id] = { start: t, line: e.line_id, fix: e.fix_build_id }; }
    else close(e.employee_id, t);
  }
  for (const emp in open) { const o = open[emp]; if (o && o.line === FIX_LINE_ID && o.fix) sums[o.fix] = (sums[o.fix] || 0) + (now - o.start); }
  const out = {}; for (const k in sums) out[k] = sums[k] / 3600000;
  return out;
}
// ===== Block 321 (Daniel 10/21: "one tap to start the fix… two people… when its done its ONE
// tap… the hour and a half he was on that fix wasn't properly calculated"): ONE FIX FLOW for a
// Body send-back (state rework) AND a fix job (kickback / customer return). The fix is a
// clock stint on the Fix-work bucket (line 15) stamped with the cab — hours are punches,
// never taps on a step. These helpers are the one place the flow's facts come from.
// Who is on a fix right now + the cab Fix-work hours so far (everyone, summed).
async function fixStatus321(buildId) {
  const seed = await db(`clock_event?select=employee_id&voided=is.false&line_id=eq.${FIX_LINE_ID}&fix_build_id=eq.${buildId}&kind=eq.clock_in&limit=2000`);
  if (!seed.length) return { on: [], hours: 0 };
  const emps = [...new Set(seed.map((x) => x.employee_id))];
  const [evs, people] = await Promise.all([
    dbAll252(`clock_event?select=employee_id,line_id,kind,fix_build_id,claimed_at&voided=is.false&employee_id=in.(${emps.join(",")})&claimed_at=gte.${new Date(Date.now() - 120 * 86400000).toISOString()}&order=claimed_at.asc,id.asc`),
    db(`employee?select=id,first_name,last_name&id=in.(${emps.join(",")})`),
  ]);
  const last = {}; for (const e of evs) last[e.employee_id] = e;
  const nm = Object.fromEntries(people.map((p) => [p.id, `${p.first_name} ${p.last_name ? p.last_name[0] + "." : ""}`.trim()]));
  const on = emps.filter((id) => last[id] && last[id].kind === "clock_in" && last[id].line_id === FIX_LINE_ID && last[id].fix_build_id === buildId)
    .map((id) => ({ id, name: nm[id] || "someone", since: last[id].claimed_at }));
  return { on, hours: fixHoursByBuild(evs)[buildId] || 0 };
}
// The line a person was on BEFORE their fix stint (Daniel: "send them back to the last line they
// were on"): the latest clock-in that is not the Fix-work bucket. Falls back to the cab own line
// when they clocked straight into the fix.
async function lineBeforeFix321(empId, fallbackLine) {
  const rows = await db(`clock_event?select=line_id,kind&voided=is.false&employee_id=eq.${empId}&kind=eq.clock_in&line_id=neq.${FIX_LINE_ID}&order=claimed_at.desc&limit=1`);
  const l = rows[0] ? Number(rows[0].line_id) : null;
  return l && l !== 14 ? l : (fallbackLine || 14);
}
// "✓ Fix done" (Daniel: "when one person taps done, both would go back to the line"): close
// EVERY open Fix-work stint on this cab (the tapper included), put each person back on the
// line they came from, and clear their focus. Punches 1 s apart — the deterministic-replay rule.
async function releaseAllFromFix321(buildId, fallbackLine, whenIso, actorId) {
  const st = await fixStatus321(buildId);
  const when = new Date(whenIso || Date.now());
  const moved = [];
  for (const p of st.on) {
    const back = await lineBeforeFix321(p.id, fallbackLine);
    await db("clock_event", { method: "POST", body: JSON.stringify({ employee_id: p.id, line_id: FIX_LINE_ID, kind: "clock_out_early", reason: p.id === actorId ? "Fix done" : "Fix done (by " + (st.on.find((x) => x.id === actorId) || { name: "a teammate" }).name + ")", claimed_at: when.toISOString() }) });
    await db("clock_event", { method: "POST", body: JSON.stringify({ employee_id: p.id, line_id: back, kind: "clock_in", claimed_at: new Date(when.getTime() + 1000).toISOString() }) });
    moved.push({ id: p.id, name: p.name, line: back });
  }
  const ids = st.on.map((p) => p.id);
  if (ids.length) await db(`employee?id=in.(${ids.join(",")})`, { method: "PATCH", body: JSON.stringify({ focus_build_id: null }) });
  return { moved, hours: st.hours };
}
// Plain words for "how long ago" on the box and the console card.
const agoWords321 = (iso) => { const m = Math.max(0, Math.round((Date.now() - new Date(iso).getTime()) / 60000)); return m < 60 ? `${m} min ago` : m < 1440 ? `${Math.floor(m / 60)} h ${m % 60 ? (m % 60) + " m " : ""}ago` : `${Math.floor(m / 1440)} day${m >= 2880 ? "s" : ""} ago`; };
// The gate for INSPECTION (Daniel 10/21 18:05): Body Shop managers (Isaac, Jason) + admins as backup.
// NOT Production managers. Written as exactly that, so a manager in some other department never gets it by accident.
const canInspect321 = (me) => Boolean(me && (me.role === "admin" || (me.role === "manager" && me.department === "Body Shop")));
// ===== Block 326 — THE BODY DEPARTMENT (Daniel 10/25 15:36: "everything needs to be seen, controlled, editable
// and reportable for the admins as well… the handoff from warehouse to production to body back to warehouse for
// crating and shipping works flawlessly… body shop wont run against a time stamp like the tv board does for
// production BUT ownership MAY want that… something we can TURN ON if needed"). Rulings 10/20 + 10/25 in
// Playbooks/61_Body_Shop_Plan.md. The department pattern: a simple HOME list (no buttons) → tap a cab → its page.
// Body steps live in body_task (never in task — production's counts/pace/recap untouched). Hours are PUNCHES on
// Body Shop time (line 13) stamped with the cab + the step (clock_event.fix_build_id + body_task_id), the
// panel-prep / fix-work pattern — the ONE-IN-HAND rule falls out of it: a person has one open stint, so tapping
// Start on another cab's step re-stamps it (the first step keeps its hours, accrues nothing more = paused).
const BODY_LINE_ID = 13;
const BODY_STEPS326 = [{ no: 1, name: "Metal & filler work" }, { no: 2, name: "Prep & final sanding" }, { no: 3, name: "Blowout, clean, mask & prime" }];
const BODY_KINDS326 = ["body", "primer"];
const BODY_PHOTO_MIN326 = 1;   // Daniel 10/25 16:17: "set the photo minimum to 1" — the in-primer set before Done in primer (independent of the product's production photo minimum)   // photo kinds: body = before primer (internal-only by default) · primer = the Done-in-primer set (customer-facing)
// Hours per cab and per step from Body Shop time punches (the Block 301 replay, keyed by cab AND step), plus who is on
// which step right now. One pass over the people who ever punched onto these cabs.
function bodyBucket326(evs, rows) {
  // Block 345 (Daniel 10/30 08:19 "like production, they can have two open tasks going at once and the math correctly figures
  // out how long each task actually took" · 08:53 "yes on a1, no limit on a2"): a step in hand is an OPEN ROW (body_step_open),
  // the clock is plain Body time, and every open row of a clocked-in person shares that time evenly — 1/k, production's rule
  // (Playbook 60). Nothing accrues while clocked out (lunch, overnight); the rows wait. Legacy: a line-13 punch stamped with a
  // step (v314–v316 wrote those) still counts as an implied row for that stint, full rate — the old rule falls out of the new one.
  const byBuild = {}, byTask = {}, onNow = {}, lastOff = {}, now = Date.now();
  const clk = {}, open = {}, per = {};
  const addRow = (emp, task, build, s, e, isOpen, legacy) => (per[emp] = per[emp] || []).push({ task: task || null, build, s, e, open: isOpen, legacy: Boolean(legacy) });
  const closeStint = (emp, t) => { const o = open[emp]; if (!o) return; if (Number(o.line) === BODY_LINE_ID) { (clk[emp] = clk[emp] || []).push({ start: o.start, end: t }); if (o.fix) addRow(emp, o.task, o.fix, o.start, t, t === now && o.live, true); } open[emp] = null; };
  for (const e of evs || []) {
    const t = new Date(e.claimed_at).getTime();
    closeStint(e.employee_id, t);
    if (e.kind === "clock_in") open[e.employee_id] = { start: t, line: e.line_id, fix: e.fix_build_id, task: e.body_task_id };
  }
  for (const emp in open) { if (open[emp]) { open[emp].live = true; closeStint(emp, now); } }
  for (const r of rows || []) { const s = new Date(r.opened_at).getTime(), e = r.closed_at ? new Date(r.closed_at).getTime() : Math.max(now, s); if (Number.isFinite(s) && e >= s) addRow(r.employee_id, r.body_task_id, r.build_id, s, e, !r.closed_at, false); }   // an open row stamped a second ahead (the +1 s punch guard) is still "on it" right now
  for (const emp in per) {
    const R = per[emp], C = clk[emp] || [];
    const cuts = new Set(); for (const r of R) { cuts.add(r.s); cuts.add(r.e); } for (const c of C) { cuts.add(c.start); cuts.add(c.end); }
    const pts = [...cuts].sort((a, b) => a - b);
    for (let i = 0; i + 1 < pts.length; i++) { const a = pts[i], b = pts[i + 1];
      if (!C.some((c) => c.start <= a && c.end >= b)) continue;   // not clocked in on Body → nothing accrues
      const K = R.filter((r) => r.s <= a && r.e >= b); if (!K.length) continue;
      const share = (b - a) / K.length;   // the 1/k split
      for (const r of K) { byBuild[r.build] = (byBuild[r.build] || 0) + share; if (r.task) byTask[r.task] = (byTask[r.task] || 0) + share; } }
    const clockedNow = C.some((c) => c.start <= now && c.end >= now);
    for (const r of R) if (r.open && r.task) (onNow[r.task] = onNow[r.task] || []).push({ emp, since: new Date(r.s).toISOString(), build: r.build, clocked: clockedNow });
  }
  const lastClose = {};
  for (const emp in per) for (const r of per[emp]) if (!r.open && r.task && (lastClose[r.task] == null || r.e > lastClose[r.task])) { lastClose[r.task] = r.e; lastOff[r.task] = emp; }
  const h = (m) => { const out = {}; for (const k in m) out[k] = m[k] / 3600000; return out; };
  return { byBuild: h(byBuild), byTask: h(byTask), onNow, lastOff };   // Block 338 shape, Block 345 rule
}

// Block 328: the punch window for a department's hours engine — the day before the OLDEST cab in the set entered the
// department (its own column), never more than 180 days; a cab with no date falls back to the 180 days.
async function punchWindow328(buildIds, col) {
  const floor = Date.now() - 180 * 86400000;
  try { const rows = await db(`build?select=${col}&id=in.(${buildIds.join(",")})&limit=400`);
    if (!rows.length || rows.some((r) => !r[col])) return new Date(floor).toISOString();
    const oldest = Math.min(...rows.map((r) => new Date(r[col]).getTime())) - 86400000;
    return new Date(Math.max(floor, oldest)).toISOString(); } catch (e) { return new Date(floor).toISOString(); }
}
async function bodyHours326(buildIds) {
  if (!buildIds.length) return { byBuild: {}, byTask: {}, onNow: {}, names: {} };
  const [seed, seedR] = await Promise.all([
    db(`clock_event?select=employee_id&voided=is.false&line_id=eq.${BODY_LINE_ID}&fix_build_id=in.(${buildIds.join(",")})&kind=eq.clock_in&limit=4000`),
    db(`body_step_open?select=employee_id&build_id=in.(${buildIds.join(",")})&limit=4000`).catch(() => []),   // Block 345
  ]);
  const emps = [...new Set(seed.concat(seedR).map((x) => x.employee_id))];
  if (!emps.length) return { byBuild: {}, byTask: {}, onNow: {}, lastOff: {}, names: {} };
  const since = await punchWindow328(buildIds, "left_production_at");   // Block 328 (reviewer): read punches only from the day before the oldest cab entered, not 180 days
  const [evs, rows, people] = await Promise.all([
    dbAll252(`clock_event?select=employee_id,line_id,kind,fix_build_id,body_task_id,claimed_at&voided=is.false&employee_id=in.(${emps.join(",")})&claimed_at=gte.${since}&order=claimed_at.asc,id.asc`),
    dbAll252(`body_step_open?select=id,employee_id,body_task_id,build_id,opened_at,closed_at&employee_id=in.(${emps.join(",")})&or=(closed_at.is.null,closed_at.gte.${since})&order=opened_at.asc,id.asc`).catch(() => []),   // Block 345: EVERY row of these people (k counts all their cabs, not only the page's)
    db(`employee?select=id,first_name,last_name&id=in.(${emps.join(",")})`),
  ]);
  const out = bodyBucket326(evs, rows);
  out.names = Object.fromEntries(people.map((p) => [p.id, `${p.first_name} ${p.last_name ? p.last_name[0] + "." : ""}`.trim()]));
  return out;
}
// The three steps for a cab, created once when it enters Body (production sign-off, both writers). Idempotent —
// a cab sent back and signed off again keeps the steps it had. Hours allowed freeze from body_standard by family.
// Block 341 (Daniel 10/28 14:40 "yes, body again, any new metal work will require more body work"): a cab that comes
// back through production after a FIX runs a FRESH round of Body steps (round N+1) — the earlier round's hours and
// allowances stay on file; body_done_at / the send-back clear so the Body list and the banner show it in Body again.
// A first entry (no rounds yet) is unchanged. A cab merely re-entering with its round still open (an admin Move, a
// sign-off while round 1 is untouched) keeps its round.
async function ensureBodyTasks326(b, actorId, opts341) {
  const have = await db(`body_task?select=id,round,state&build_id=eq.${b.id}&order=round.desc,step_no.asc`);
  let round = 1;
  if (have.length) {
    const cur = Number(have[0].round || 1);
    const afterFix = Boolean(opts341 && opts341.afterFix);
    if (!afterFix) return false;
    const curRows = have.filter((t) => Number(t.round || 1) === cur);
    if (curRows.every((t) => t.state === "not_started")) {   // reviewer: an untouched round is reused, not buried under a dead one
      await db(`build?id=eq.${b.id}`, { method: "PATCH", body: JSON.stringify({ body_done_at: null, body_done_by: null, wh_sent_back_at: null, wh_sent_back_by: null, wh_sent_back_reason: null, stage: null, body_moved_to_build_at: null }) });
      logEvent("body.entered", actorId || null, { build_id: b.id, order_number: b.order_number, steps: 3, round: cur, reused: true });
      return false;
    }
    round = cur + 1;
    await db(`build?id=eq.${b.id}`, { method: "PATCH", body: JSON.stringify({ body_done_at: null, body_done_by: null, wh_sent_back_at: null, wh_sent_back_by: null, wh_sent_back_reason: null, stage: null, body_moved_to_build_at: null }) });   // reviewer: the sign-off's row may not carry stage — clear it outright
    logEvent("body.new_round", actorId || null, { build_id: b.id, order_number: b.order_number, round, after_fix: true });
  }
  const [prod] = b.part_number ? await db(`product?select=family&part_number=eq.${encodeURIComponent(b.part_number)}`) : [null];
  const fam = prod && prod.family ? prod.family : "";
  const std = fam ? await db(`body_standard?select=step_no,hours&family=eq.${encodeURIComponent(fam)}`) : [];
  const dflt = { 1: 7, 2: 3, 3: 3 };
  await db("body_task", { method: "POST", body: JSON.stringify(BODY_STEPS326.map((s) => ({ build_id: b.id, round, step_no: s.no, name: s.name, state: "not_started", hours_allowed: (std.find((r) => Number(r.step_no) === s.no) || { hours: dflt[s.no] }).hours }))) });
  logEvent("body.entered", actorId || null, { build_id: b.id, order_number: b.order_number, family: fam, steps: 3, round });
  try { const ids = await floorMgrIds220("inspect"); void notify("body.cab_arrived", ids, `Order ${b.order_number}${b.cab_number ? ` (Cab #${b.cab_number})` : ""} is in Body`, `Signed off from production — its three Body steps are ready to tap. Nothing starts until someone taps the first step.`, "/body/" + encodeURIComponent(b.order_number)); } catch (e) { console.error("body arrive notify:", e && e.message); }
  return true;
}
// Everything one Body cab card / page needs.
async function bodyStatus326(builds) {
  const ids = builds.map((b) => b.id);
  if (!ids.length) return [];
  const [tasks, hrs, prods] = await Promise.all([
    dbAll252(`body_task?select=id,build_id,round,step_no,name,hours_allowed,state,started_by,started_at,completed_by,completed_at&build_id=in.(${ids.join(",")})&order=build_id.asc,round.asc,step_no.asc`).then((all) => { const maxR = {}; for (const t of all) maxR[t.build_id] = Math.max(maxR[t.build_id] || 1, Number(t.round || 1)); return all.filter((t) => Number(t.round || 1) === maxR[t.build_id]); }),   // Block 341: the LATEST round is the cab's Body work now
    bodyHours326(ids),
    db("product?select=part_number,family"),
  ]);
  const famOf = Object.fromEntries(prods.map((p) => [String(p.part_number).toUpperCase(), p.family]));
  const who = new Set(); for (const t of tasks) { if (t.started_by) who.add(t.started_by); if (t.completed_by) who.add(t.completed_by); }
  const extra = [...who].filter((id) => !hrs.names[id]);
  if (extra.length) for (const p of await db(`employee?select=id,first_name,last_name&id=in.(${extra.join(",")})`)) hrs.names[p.id] = `${p.first_name} ${p.last_name ? p.last_name[0] + "." : ""}`.trim();
  return builds.map((b) => {
    const steps = tasks.filter((t) => t.build_id === b.id).map((t) => ({ ...t, hours: Math.round((hrs.byTask[t.id] || 0) * 10) / 10, on: (hrs.onNow[t.id] || []).map((o) => ({ id: o.emp, name: hrs.names[o.emp] || "someone", since: o.since })), lastOff: (hrs.lastOff || {})[t.id] || null }));   // Block 338: lastOff
    const allowed = steps.reduce((s, t) => s + Number(t.hours_allowed || 0), 0);
    const hours = Math.round(steps.reduce((sum, t) => sum + (hrs.byTask[t.id] || 0), 0) * 10) / 10;   // tenths on every screen (payroll-style); the audit rows keep hundredths · Block 341 (reviewer): the LATEST round's steps only, so "X of Y h" compares like with like
    const done = steps.filter((t) => t.state === "complete").length;
    const cur = steps.find((t) => t.state === "in_progress") || steps.find((t) => t.state === "not_started");
    const onNames = steps.flatMap((t) => t.on.map((o) => o.name));
    const inFix = b.state === "rework" || b.state === "fix_job";
    const status = b.body_moved_to_build_at ? "moved to the Build department" : b.body_done_at ? `done in primer ${phxDate(new Date(b.body_done_at).getTime())}` : inFix
      ? "back in production for a fix" : !steps.length ? "no Body steps yet" : done === steps.length ? (bodyLocked339(b, steps) ? "sent back from crating — reopen the step it needs" : "all steps done — waiting for ✓ Done in primer")
      : cur ? `${cur.name} · ${cur.hours} of ${Number(cur.hours_allowed)} h${cur.state === "in_progress" ? (cur.on.length ? ` · ${cur.on.map((o) => o.name).join(" + ")} on it` : " · paused") : " · not started"}` : "";
    return { b, family: famOf[String(b.part_number || "").toUpperCase()] || "", steps, allowed, hours, done, total: steps.length, onNames: [...new Set(onNames)], status, inFix, names: hrs.names, round: steps[0] ? Number(steps[0].round || 1) : 1 };   // Block 341: +round
  });
}
// The clock stint helpers. A Body start = (close the open stint) + clock_in on 13 stamped cab + step. A pause or a
// step done = close the 13 stint + clock_in on the line you came from (Body Shop dept → plain Body Shop time; a
// helper from production → their last production line; nothing known → Shop time).
async function bodyLineAfter326(empId, me) {
  if (me && me.department === "Body Shop") return BODY_LINE_ID;
  const rows = await db(`clock_event?select=line_id&voided=is.false&employee_id=eq.${empId}&kind=eq.clock_in&line_id=neq.${BODY_LINE_ID}&order=claimed_at.desc&limit=1`);
  const l = rows[0] ? Number(rows[0].line_id) : null;
  if (l && l !== 14) return l;
  return me && me.department === "Warehouse" ? 9 : me && me.department === "Build" ? 12 : SHOP_LINE_ID;
}
const bodyChip326 = (st) => st.b.body_moved_to_build_at ? `<span class="chip" style="background:#3a2f10;color:#ffd60a">Build department</span>` : st.b.body_done_at ? `<span class="chip ok">&#10003; Done in primer</span>` : st.inFix ? `<span class="chip" style="background:#3a1520;color:#ff8fa3">Back in production</span>` : st.done === st.total && st.total ? `<span class="chip" style="background:#173a2b;color:#5edb84">Steps done</span>` : st.steps.some((t) => t.state === "in_progress" && t.on.length) ? `<span class="chip" style="background:#10233a;color:#5eaeff">&#9881; In progress</span>` : st.done || st.steps.some((t) => t.state === "in_progress") ? `<span class="chip" style="background:#2c2c2e;color:#c7c7cc">&#9208; Paused</span>` : `<span class="chip unv">Waiting</span>`;
